#!/usr/bin/env bash
# Question 1: Pod archive-app stuck. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "files" >/dev/null 2>&1 || kubectl get namespace "files" >/dev/null
timeout 60 bash -c "until kubectl -n 'files' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: archive-pv
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/archive
    type: DirectoryOrCreate
  nodeAffinity:
    required:
      nodeSelectorTerms:
        - matchExpressions:
            - { key: kubernetes.io/hostname, operator: In, values: [worker-1] }
EOF
# Faults append shell assignments here (sc=..., pin=...); after reads them back. A file rather than
# shell variables, because a layered question runs every fault in its own subshell.
: > "/var/tmp/cka-q1.claim"

(
case "${Q1_FAULT}" in
  storageclass-mismatch)
    echo 'sc=fast' >> "/var/tmp/cka-q1.claim"
    ;;
  access-mode-mismatch)
    echo 'mode=ReadWriteMany' >> "/var/tmp/cka-q1.claim"
    ;;
  claim-too-large)
    echo 'size=2Gi' >> "/var/tmp/cka-q1.claim"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
  pv-released-claimref)
    kubectl apply -f - <<< '{"apiVersion":"v1","kind":"List","items":[{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"archive"'","namespace":"'"files"'"},"spec":{"storageClassName":"manual","accessModes":["ReadWriteOnce"],"resources":{"requests":{"storage":"500Mi"}}}},{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"archive"'-app","namespace":"'"files"'"},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sleep","1d"],"volumeMounts":[{"name":"data","mountPath":"/data"}]}],"volumes":[{"name":"data","persistentVolumeClaim":{"claimName":"'"archive"'"}}]}}]}'
    kubectl -n "files" wait --for=jsonpath='{.status.phase}'=Bound "pvc/archive" --timeout=60s
    kubectl -n "files" delete pod "archive-app" --wait=true
    kubectl -n "files" delete pvc "archive" --wait=true
    for _ in $(seq 1 30); do
      [[ "$(kubectl get pv "archive-pv" -o jsonpath='{.status.phase}')" == Released ]] && break
      sleep 1
    done
    [[ "$(kubectl get pv "archive-pv" -o jsonpath='{.status.phase}')" == Released ]] || { echo "PV is not Released" >&2; exit 1; }
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_3}" in
  pod-node-pin)
    echo 'pin=worker-2' >> "/var/tmp/cka-q1.claim"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
sc=manual mode=ReadWriteOnce size=500Mi pin=
. "/var/tmp/cka-q1.claim"
sel=''
[[ -z "$pin" ]] || sel=',"nodeSelector":{"kubernetes.io/hostname":"'"$pin"'"}'
kubectl apply -f - <<< '{"apiVersion":"v1","kind":"List","items":[{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"archive"'","namespace":"'"files"'"},"spec":{"storageClassName":"'"$sc"'","accessModes":["'"$mode"'"],"resources":{"requests":{"storage":"'"$size"'"}}}},{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"archive"'-app","namespace":"'"files"'"},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sleep","1d"],"volumeMounts":[{"name":"data","mountPath":"/data"}]}],"volumes":[{"name":"data","persistentVolumeClaim":{"claimName":"'"archive"'"}}]'"$sel"'}}]}'
sleep 10
[[ "$(kubectl -n "files" get pod "archive-app" -o jsonpath='{.status.phase}')" == Pending ]] || { echo "archive-app is not Pending" >&2; exit 1; }
)
